using DriveOS.Application.Abstractions.Messaging; using DriveOS.Application.Abstractions.Time; using DriveOS.Modules.Workforce.Application.Persistence; using DriveOS.Modules.Workforce.Domain.LeavePolicies; using DriveOS.SharedKernel.Identifiers; using DriveOS.SharedKernel.Results;
namespace DriveOS.Modules.Workforce.Application.LeavePolicies;
public sealed class CreateLeavePolicyCommandHandler(ILeavePolicyRepository repo,IWorkforceUnitOfWork uow,IClock clock):ICommandHandler<CreateLeavePolicyCommand,LeavePolicyId>{public async Task<Result<LeavePolicyId>> Handle(CreateLeavePolicyCommand c,CancellationToken ct){if(await repo.FindByCodeAsync(c.OrganizationId,c.CountryCode,c.Code,ct)is not null)return Result.Failure<LeavePolicyId>(LeavePolicyErrors.DuplicateCode);var now=clock.UtcNow;var r=LeavePolicy.Create(c.LeavePolicyId,c.OrganizationId,c.CountryCode,c.Code,c.Name,c.Category,c.IsPaid,c.RequiresApproval,c.RequiresEvidence,c.AllowHalfDay,c.MinimumNoticeDays,c.MaximumConsecutiveDays,now);if(r.IsFailure)return Result.Failure<LeavePolicyId>(r.Error);r.Value.SetCreatedAudit(now,c.ActorUserId);repo.Add(r.Value);await uow.CommitAsync(ct);return Result.Success(r.Value.Id);}}
public sealed class UpdateLeavePolicyCommandHandler(ILeavePolicyRepository repo,IWorkforceUnitOfWork uow,IClock clock):ICommandHandler<UpdateLeavePolicyCommand>{public async Task<Result> Handle(UpdateLeavePolicyCommand c,CancellationToken ct){var p=await repo.GetByIdForUpdateAsync(c.OrganizationId,c.LeavePolicyId,ct);if(p is null)return Result.Failure(LeavePolicyErrors.NotFound);var dup=await repo.FindByCodeAsync(c.OrganizationId,c.CountryCode,c.Code,ct);if(dup is not null&&dup.Id!=c.LeavePolicyId)return Result.Failure(LeavePolicyErrors.DuplicateCode);var r=p.Update(c.CountryCode,c.Code,c.Name,c.Category,c.IsPaid,c.RequiresApproval,c.RequiresEvidence,c.AllowHalfDay,c.MinimumNoticeDays,c.MaximumConsecutiveDays,clock.UtcNow,c.ActorUserId);if(r.IsFailure)return r;await uow.CommitAsync(ct);return Result.Success();}}
public sealed class DeactivateLeavePolicyCommandHandler(ILeavePolicyRepository repo,IWorkforceUnitOfWork uow,IClock clock):ICommandHandler<DeactivateLeavePolicyCommand>{public async Task<Result> Handle(DeactivateLeavePolicyCommand c,CancellationToken ct){var p=await repo.GetByIdForUpdateAsync(c.OrganizationId,c.LeavePolicyId,ct);if(p is null)return Result.Failure(LeavePolicyErrors.NotFound);var r=p.Deactivate(clock.UtcNow,c.ActorUserId);if(r.IsFailure)return r;await uow.CommitAsync(ct);return Result.Success();}}
public sealed class ReactivateLeavePolicyCommandHandler(ILeavePolicyRepository repo,IWorkforceUnitOfWork uow,IClock clock):ICommandHandler<ReactivateLeavePolicyCommand>{public async Task<Result> Handle(ReactivateLeavePolicyCommand c,CancellationToken ct){var p=await repo.GetByIdForUpdateAsync(c.OrganizationId,c.LeavePolicyId,ct);if(p is null)return Result.Failure(LeavePolicyErrors.NotFound);var r=p.Reactivate(clock.UtcNow,c.ActorUserId);if(r.IsFailure)return r;await uow.CommitAsync(ct);return Result.Success();}}
public sealed class GetLeavePolicyQueryHandler(ILeavePolicyRepository repo):IQueryHandler<GetLeavePolicyQuery,LeavePolicyResponse>{public async Task<Result<LeavePolicyResponse>> Handle(GetLeavePolicyQuery q,CancellationToken ct){var p=await repo.GetByIdAsync(q.OrganizationId,q.LeavePolicyId,ct);return p is null?Result.Failure<LeavePolicyResponse>(LeavePolicyErrors.NotFound):Result.Success(Map(p));} internal static LeavePolicyResponse Map(LeavePolicy p)=>new(p.Id.Value,p.CountryCode,p.Code,p.Name,p.Category.ToString(),p.IsPaid,p.RequiresApproval,p.RequiresEvidence,p.AllowHalfDay,p.MinimumNoticeDays,p.MaximumConsecutiveDays,p.Status.ToString());}
public sealed class GetLeavePoliciesQueryHandler(ILeavePolicyRepository repo):IQueryHandler<GetLeavePoliciesQuery,IReadOnlyList<LeavePolicyResponse>>{public async Task<Result<IReadOnlyList<LeavePolicyResponse>>> Handle(GetLeavePoliciesQuery q,CancellationToken ct)=>Result.Success<IReadOnlyList<LeavePolicyResponse>>((await repo.ListAsync(q.OrganizationId,q.CountryCode,q.Status,ct)).Select(GetLeavePolicyQueryHandler.Map).ToArray());}
